    let query_sql = "-- @name Recorded\n-- @returns :many\nSELECT id FROM audit_logs WHERE data->>$1 = $2 AND data #>> $3 IS NOT NULL AND data @> $4 AND data ? $5 AND data->$6 IS NOT NULL;";

